":"integrated-systems","domain":null,"description":"Computer aided engineering products","sector":"Technology — Software","hq":"Santa Clara, CA","status":"realized","invested_year":1987,"exit_year":1990,"fund_name":null,"source_url":"https://www.summitpartners.com/companies/integrated-systems","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Chips and Technologies","slug":"chips-and-technologies","domain":null,"description":"Application-specific integrated circuits","sector":"Technology — Semiconductors & Electronics","hq":"Milpitas, CA","status":"realized","invested_year":1986,"exit_year":1987,"fund_name":null,"source_url":"https://www.summitpartners.com/companies/chips-and-technologies","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Telebit Corporation","slug":"telebit","domain":null,"description":"Products for data communication networks","sector":"Technology — Communications Technology","hq":"Chelmsford, MA","status":"realized","invested_year":1986,"exit_year":1996,"fund_name":null,"source_url":"https://www.summitpartners.com/companies/telebit-corporation","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"AdvaCare","slug":"advacare","domain":null,"description":"Physician office management","sector":"Healthcare & Life Sciences — Healthcare Services","hq":"Dallas, TX","status":"realized","invested_year":1986,"exit_year":1992,"fund_name":null,"source_url":"https://www.summitpartners.com/companies/advacare","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Employee Benefit Plans","slug":"employee-benefit-plans","domain":null,"description":"Health and accident insurance services","sector":"Healthcare & Life Sciences — Healthcare Services, Financial Services","hq":"Minneapolis, MN","status":"realized","invested_year":1986,"exit_year":1989,"fund_name":null,"source_url":"https://www.summitpartners.com/companies/employee-benefit-plans","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"FSI International","slug":"fsi-international","domain":null,"description":"Processing equipment for semiconductor manufacturing","sector":"Technology — Semiconductors & Electronics","hq":"Chaska, MN","status":"realized","invested_year":1985,"exit_year":1989,"fund_name":null,"source_url":"https://www.summitpartners.com/companies/fsi-international","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Aehr Test Systems","slug":"aehr-test-systems","domain":"aehr.com","description":"Semiconductor test and burn-in equipment","sector":"Technology — Semiconductors & Electronics","hq":"Menlo Park, CA","status":"realized","invested_year":1985,"exit_year":1997,"fund_name":null,"source_url":"https://www.summitpartners.com/companies/aehr-test-systems","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Keyfactor","slug":"keyfactor","domain":null,"description":"Trust infrastructure and machine identity security company.","sector":null,"hq":"Atlanta, GA and Stockholm, Sweden","status":null,"invested_year":2026,"exit_year":null,"fund_name":null,"source_url":"https://www.summitpartners.com/news/keyfactor-announces-strategic-growth-investment-led-by-summit-partners-to-expand-leadership-in-securing-the-ai-and-post-quantum-enterprise","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"PrismHR","slug":"prismhr","domain":null,"description":"Provider of software for human resource outsourcing (HRO) service providers.","sector":null,"hq":"Southborough, MA","status":null,"invested_year":2017,"exit_year":null,"fund_name":null,"source_url":"https://www.summitpartners.com/news/prismhr-announces-investment-from-summit-partners-to-power-ongoing-growth","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null}],"deals":[]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'Summit Partners'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'Summit Partners'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'summitpartners.com Webflow CMS portfolio list (/portfolio?b6676ed8_page=1..5, 411 items, matches sitemap /companies/*) plus every /companies/<slug> page for invested year, status, location, website; 2 more from Summit''s own /news releases', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'Summit Partners', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
